import itertools

teams = ['A', 'B', 'C', 'D']
all_pairings = list(itertools.combinations(teams, 2))

def is_valid_round(pairings):
    flat_list = []
    for p in pairings:
        flat_list.extend(p)
    return sorted(flat_list) == sorted(teams)

possible_rounds = []
for combo in itertools.combinations(all_pairings, 2):
    if is_valid_round(combo):
        # Store as a list of frozensets for easy comparison
        possible_rounds.append([frozenset(p) for p in combo])

def solve():
    for r1 in possible_rounds:
        # Constraint: Team A cannot play Team B in Round 1
        if frozenset(['A', 'B']) in r1:
            continue

        for r2 in possible_rounds:
            # Constraint: Team C plays Team D in Round 2
            if frozenset(['C', 'D']) not in r2:
                continue

            for r3 in possible_rounds:
                # Check if any team plays the same opponent twice across 3 rounds.
                # A valid schedule for 4 teams over 3 rounds usually means each team 
                # plays every other team exactly once (Round Robin).
                all_used = set()
                for round_pairings in [r1, r2, r3]:
                    for p in round_pairings:
                        all_used.add(p)

                if len(all_used) == 6: # There are exactly 6 unique pairings for 4 teams
                    return [r1, r2, r3]
    return None

result = solve()
print(result)

